tests.code:
for bad in ['ten', '4.5', '', '-1', '151']:
    try:
        parse_age(bad)
    except ValueError:
        pass
    else:
        raise AssertionError(f'parse_age({bad!r}) should raise ValueError')

try:
    valid_ages(['3', None])
except ValueError:
    raise AssertionError('None is not text: that error should not become a ValueError')
except Exception:
    pass
else:
    raise AssertionError('valid_ages hid an error that is not a ValueError: catch only ValueError')

for bad in ['ten', '4.5', '', '-1', '151']:
    try:
        parse_age(bad)
    except ValueError as e:
        assert str(e).strip(), f'parse_age({bad!r}) should raise ValueError with a message saying what is wrong'
    else:
        raise AssertionError(f'parse_age({bad!r}) should raise ValueError')

_real = parse_age
try:
    for _exc in (TypeError, KeyError):
        def parse_age(text, _exc=_exc):
            raise _exc('unexpected')
        try:
            valid_ages(['1'])
        except _exc:
            pass
        else:
            raise AssertionError(f'valid_ages hid a {_exc.__name__}: catch only ValueError')
finally:
    parse_age = _real

steps.solution:
def parse_age(text):
    age = int(text.strip())
    if not 0 <= age <= 150:
        raise ValueError(f"age must be between 0 and 150, not {age}")
    return age


def valid_ages(texts):
    ages = []
    for t in texts:
        try:
            ages.append(parse_age(t))
        except ValueError:
            pass
    return ages

